        is_interim = True
    elif ('interim' in acc_name) or ('input' in acc_name) or ('وسيط' in acc_name) or ('استلام' in acc_name) or ('مستلم' in acc_name) or ('مؤقت' in acc_name) or ('وارد' in acc_name):
